package kotobaya.sync.client.remint

import kotobaya.sync.DefaultCanonicalJson
import java.io.File
import kotlin.test.Test
import kotlin.test.fail

/**
 * Keeps `commonTest/.../sync/client/remint/RemintScenarios.kt` (the canonical compact JSON of each file
 * in `contracts/sync/examples/remint-scenarios/`) identical to the contract files, so the client-side
 * scenario tests run on jvm and js. On drift the regenerated file is written under
 * `core/build/sync-drift/` and the test fails; copy it over and commit.
 */
class RemintScenariosDriftTest {
    private val root = File("../contracts/sync/examples/remint-scenarios")
    private val target = File("src/commonTest/kotlin/kotobaya/sync/client/remint/RemintScenarios.kt")

    @Test
    fun embeddedScenariosMatchContracts() {
        val names = root.listFiles()!!.map { it.name }.filter { it.endsWith(".json") }.sorted()
        val entries = names.joinToString("") { name ->
            val decoded = DefaultCanonicalJson.decode(root.resolve(name).readText())
            val canonical = DefaultCanonicalJson.encode(decoded.value ?: fail("$name: ${decoded.error}"))
            "        \"$name\" to\n            \"${escape(canonical)}\",\n"
        }
        val source = "package kotobaya.sync.client.remint\n\n" +
            "/**\n" +
            " * GENERATED by the jvm test `RemintScenariosDriftTest` from `contracts/sync/examples/remint-scenarios/`\n" +
            " * (canonical compact JSON, keyed by file name); do not edit.\n" +
            " */\n" +
            "internal object RemintScenarios {\n" +
            "    val files: Map<String, String> = mapOf(\n" +
            entries +
            "    )\n" +
            "}\n"
        if (target.exists() && target.readText() == source) return
        val out = File("build/sync-drift").apply { mkdirs() }.resolve(target.name)
        out.writeText(source)
        fail("${target.path} drifted from contracts/sync/examples/remint-scenarios: regenerated at ${out.absolutePath}; copy it over and commit")
    }

    private fun escape(s: String): String = buildString {
        for (c in s) {
            when (c) {
                '\\' -> append("\\\\")
                '"' -> append("\\\"")
                '$' -> append("\\$")
                '\n' -> append("\\n")
                '\r' -> append("\\r")
                '\t' -> append("\\t")
                else -> if (c.code < 0x20 || c.code > 0x7e) append("\\u%04x".format(c.code)) else append(c)
            }
        }
    }
}
